sys_atf_step.inputs:
(function(outputs, steps, stepResult) {
  var ad = new x_fed_day2_ops.AdHybridClient();
  // 1. A synced object must classify as AD-mastered.
  if (ad.isAdMastered({ onPremisesSyncEnabled: true }) !== true) {
    stepResult.setFailed('a synced object (onPremisesSyncEnabled=true) did not classify as AD-mastered');
    return;
  }
  // 2. The AD-leg disable must be ACCEPTED FOR DISPATCH. It must NOT assert
  // post-state (no accountEnabled, no synced) -- ok/dispatched means the ECC
  // job was queued, never that the change took. A genuine post-state
  // assertion only comes from getUserAd/isGroupMemberAd against a live DC,
  // which test_mode cannot exercise (see atf-hybrid-verify-sync-projection.xml).
  var r = ad.disableUserAd('test-user-0001');
  if (!(r && r.ok === true && r.dispatched === true)) {
    stepResult.setFailed('AD-leg disableUserAd did not report a successful dispatch: ' + JSON.stringify(r));
    return;
  }
  if (r.hasOwnProperty('accountEnabled') || r.hasOwnProperty('synced')) {
    stepResult.setFailed('AD-leg disableUserAd return carries an observation-shaped field (accountEnabled/synced) -- P0-4 regressed: ' + JSON.stringify(r));
    return;
  }
  stepResult.setSuccess();
})(outputs, steps, stepResult);
